sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float angle;
uniform float start;
uniform float end;
uniform float curve;
uniform float mirror;
uniform float invert;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float a = radians(angle);
    float t = dot(coord / size - float2(0.5), float2(cos(a), sin(a))) + 0.5;
    if (mirror > 0.5) t = 1.0 - abs(2.0 * t - 1.0);
    float k = pow(smoothstep(start, max(end, start + 0.001), t), curve);
    if (invert > 0.5) k = 1.0 - k;
    return fin(c, c * k, opacity);
}
